-- ---------- modules ----------
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('quimica-7','quimica','Módulo 7','Ligação metálica','Ligação metálica é explicada pelo modelo do mar de elétrons: cátions metálicos organizados em rede cristalina são estabilizados por elétrons deslocalizados. Esse modelo explica a condutibilidade elétrica e térmica, o brilho, a maleabilidade, a ductilidade e a formação de ligas.','["Metais conduzem eletricidade porque possuem elétrons livres que se movimentam pela estrutura.","Maleabilidade e ductilidade surgem porque as camadas de cátions podem deslizar sem romper a ligação.","Ligas metálicas são misturas homogêneas de metais ou de metal com outro elemento, feitas para melhorar propriedades.","Bronze é cobre com estanho; latão é cobre com zinco; aço inoxidável envolve ferro, carbono, cromo e níquel.","O nióbio pode aumentar a resistência mecânica do aço sem prejudicar a soldabilidade e a tenacidade."]'::jsonb,'[["Mar de elétrons","Modelo em que elétrons deslocalizados transitam entre cátions metálicos."],["Ductilidade","Capacidade de formar fios."],["Maleabilidade","Capacidade de formar lâminas."],["Liga metálica","Mistura sólida com propriedades metálicas."],["Tenacidade","Capacidade de deformar sem romper."]]'::jsonb,'["ligação metálica","mar de elétrons","condutibilidade","liga metálica","bronze","latão","aço inoxidável","nióbio","maleabilidade","ductilidade"]'::jsonb,'["metais têm elétrons deslocalizados","ligas ajustam resistência e durabilidade","aço com nióbio pode ficar mais resistente","bronze contém cobre e estanho","latão contém cobre e zinco"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('quimica-8','quimica','Módulo 8','Alotropia e retículos','Alotropia ocorre quando substâncias diferentes são formadas pelo mesmo elemento químico. Carbono pode formar diamante, grafite e fulereno; oxigênio forma O2 e O3; fósforo e enxofre também têm formas alotrópicas. O módulo também compara cristais moleculares, covalentes, iônicos e metálicos.','["Alótropos possuem o mesmo elemento químico, mas estruturas e propriedades diferentes.","Diamante é duro e isolante; grafite é macio e conduz eletricidade por sua estrutura em camadas.","Cristais moleculares tendem a ter baixa temperatura de fusão e baixa condução.","Cristais iônicos conduzem eletricidade quando fundidos ou dissolvidos em água.","Cristais covalentes costumam ter alta temperatura de fusão, como diamante e quartzo."]'::jsonb,'[["Alotropia","Fenômeno de um mesmo elemento formar substâncias simples diferentes."],["Cristal molecular","Estrutura mantida por interações intermoleculares."],["Cristal iônico","Rede de cátions e ânions unidos por atração eletrostática."],["Cristal covalente","Rede extensa de ligações covalentes."],["Grafite","Alótropo do carbono que conduz eletricidade."]]'::jsonb,'["alotropia","diamante","grafite","fulereno","ozônio","gás oxigênio","retículo iônico","retículo covalente","retículo molecular","retículo metálico"]'::jsonb,'["O2 e O3 são alótropos do oxigênio","grafite conduz eletricidade","diamante e grafite são carbono","NaCl é retículo iônico","sacarose é cristal molecular"]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('quimica-9','quimica','Módulo 9','Geometria e polaridade','A geometria molecular depende da repulsão entre nuvens eletrônicas ao redor do átomo central. Moléculas lineares, angulares, trigonais planas e piramidais podem ser previstas observando pares ligantes e pares não ligantes. A polaridade das ligações depende da diferença de eletronegatividade; a polaridade da molécula depende da soma dos dipolos e da geometria.','["Duas nuvens eletrônicas ao redor do átomo central tendem a formar geometria linear.","Três átomos ligantes sem par livre podem formar geometria trigonal plana.","Pares de elétrons não ligantes podem gerar geometria angular ou piramidal.","Ligação entre átomos iguais é apolar; entre átomos com eletronegatividade diferente tende a ser polar.","Uma molécula pode ter ligações polares e ser apolar se os dipolos se anularem pela simetria."]'::jsonb,'[["Geometria molecular","Forma espacial da molécula."],["Eletronegatividade","Tendência de atrair elétrons em uma ligação."],["Dipolo","Separação de cargas parciais em uma ligação ou molécula."],["Molécula polar","Molécula com dipolo resultante diferente de zero."],["Molécula apolar","Molécula sem dipolo resultante."]]'::jsonb,'["geometria linear","geometria angular","trigonal plana","piramidal","eletronegatividade","dipolo","ligação polar","molécula polar","simetria","pares livres"]'::jsonb,'["CO2 é linear e apolar","H2O é angular e polar","NH3 é piramidal","ligações entre átomos iguais são apolares","pares livres alteram a geometria"]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('quimica-10','quimica','Módulo 10','Interações intermoleculares','Interações intermoleculares são forças entre moléculas. Dipolo instantâneo-dipolo induzido aparece em todas as moléculas e domina em substâncias apolares. Dipolo-dipolo ocorre entre moléculas polares. Ligações de hidrogênio aparecem quando H está ligado a F, O ou N. A intensidade dessas interações influencia ebulição, fusão, solubilidade e miscibilidade.','["Forças de London existem em todas as substâncias moleculares, mas são decisivas nas apolares.","Dipolo-dipolo ocorre entre moléculas polares com polos permanentes.","Ligação de hidrogênio é uma interação intensa envolvendo H ligado a F, O ou N.","Interações mais fortes aumentam a temperatura de ebulição, se o tamanho molecular for comparável.","Semelhante dissolve semelhante: polar tende a dissolver polar; apolar tende a dissolver apolar."]'::jsonb,'[["London","Interação dipolo instantâneo-dipolo induzido."],["Dipolo-dipolo","Atração entre moléculas polares."],["Ligação de hidrogênio","Interação forte envolvendo H ligado a F, O ou N."],["Miscibilidade","Capacidade de dois líquidos se misturarem."],["Solubilidade","Capacidade de uma substância dissolver em outra."]]'::jsonb,'["London","dipolo-dipolo","ligação de hidrogênio","temperatura de ebulição","solubilidade","polaridade","miscibilidade","moléculas apolares","H ligado a F O N","tamanho molecular"]'::jsonb,'["água faz ligação de hidrogênio","moléculas apolares interagem por London","maior interação aumenta ebulição","polar dissolve polar","hexano é apolar"]'::jsonb,30)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('portugues-8','portugues','Módulo 8','Figuras II','O módulo trabalha figuras de implicação mútua e intensidade. Metonímia troca um termo por outro ligado por relação de proximidade ou associação. Sinédoque envolve relação entre parte e todo. Hipérbole exagera; eufemismo suaviza; gradação organiza ideias em sequência crescente ou decrescente.','["Metonímia depende de relação de contiguidade, como autor pela obra ou lugar pela instituição.","Sinédoque pode trocar parte pelo todo ou todo pela parte.","Hipérbole usa exagero intencional para intensificar sentido.","Eufemismo suaviza expressões duras, desagradáveis ou ofensivas.","Gradação cria progressão de intensidade, ordem ou importância."]'::jsonb,'[["Metonímia","Substituição por relação de proximidade."],["Sinédoque","Substituição envolvendo parte e todo."],["Hipérbole","Exagero expressivo."],["Eufemismo","Suavização de uma ideia."],["Gradação","Sequência progressiva de ideias."]]'::jsonb,'["metonímia","sinédoque","hipérbole","eufemismo","gradação","contiguidade","parte pelo todo","exagero","suavização","intensidade"]'::jsonb,'["metonímia não é comparação direta","hipérbole exagera para expressar","eufemismo reduz impacto","gradação pode ser crescente","sinédoque usa parte e todo"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('portugues-9','portugues','Módulo 9','Figuras III','As figuras de oposição exploram contrastes. Antítese aproxima termos opostos explícitos. Paradoxo reúne ideias aparentemente incompatíveis. Ironia diz algo para sugerir o contrário ou um sentido crítico diferente. Preterição finge não falar de algo enquanto fala indiretamente.','["Antítese cria contraste direto entre palavras ou ideias opostas.","Paradoxo aproxima ideias que parecem se excluir, mas produzem reflexão.","Ironia depende do contexto e da diferença entre o dito e o pretendido.","Preterição pode reforçar um argumento ao declarar que não vai abordar algo.","O efeito argumentativo dessas figuras costuma depender de leitura atenta do contexto."]'::jsonb,'[["Antítese","Aproximação de ideias opostas."],["Paradoxo","Convivência de sentidos aparentemente incompatíveis."],["Ironia","Dito que sugere sentido diferente, muitas vezes contrário."],["Preterição","Fingir não falar enquanto se fala indiretamente."],["Contraste","Relação de oposição contextual."]]'::jsonb,'["antítese","paradoxo","ironia","preterição","oposição","contraste","crítica","contexto","argumentação","oximoro"]'::jsonb,'["antítese opõe termos explícitos","paradoxo combina ideias incompatíveis","ironia exige contexto","preterição fala indiretamente","oximoro é forma de paradoxo"]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('portugues-10','portugues','Módulo 10','Figuras IV','O módulo trata de repetição e sonoridade. Anáfora repete palavras ou expressões. Polissíndeto repete conjunções. Quiasmo cruza a ordem dos termos. Pleonasmo repete informações de modo expressivo. Aliteração, assonância, onomatopeia e paronomásia exploram sons.','["Anáfora cria ritmo e insistência pela repetição no início ou ao longo de enunciados.","Polissíndeto repete conjunções para somar ações, criar ritmo ou prolongar uma cena.","Quiasmo inverte a ordem dos termos, como histórias de vida e vidas de histórias.","Aliteração repete sons consonantais; assonância repete sons vocálicos.","Paronomásia aproxima palavras parecidas no som; onomatopeia imita sons."]'::jsonb,'[["Anáfora","Repetição recorrente de palavras ou expressões."],["Polissíndeto","Repetição de conjunções."],["Quiasmo","Cruzamento/inversão de termos."],["Aliteração","Repetição de sons consonantais."],["Paronomásia","Jogo com palavras de som parecido."]]'::jsonb,'["anáfora","polissíndeto","quiasmo","pleonasmo","aliteração","assonância","onomatopeia","paronomásia","repetição","sonoridade"]'::jsonb,'["anáfora repete expressões","polissíndeto repete conjunções","quiasmo cruza termos","aliteração usa consoantes","assonância usa vogais"]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('portugues-6','portugues','Módulo 6','Linguagem figurada','O módulo abre a unidade de figuras de linguagem distinguindo sentido literal (denotativo, dicionarizado) de sentido figurado (conotativo, dependente de contexto). Mostra que a maior parte das figuras de linguagem nasce de dois grandes mecanismos: relação de semelhança entre dois termos ou relação de implicação mútua, em que um elemento concreto evoca outro por proximidade lógica ou cultural, sem precisar de comparação explícita.','["Sentido literal é o significado de dicionário, sem desvio em relação ao uso convencional da palavra.","Sentido figurado ocorre quando a palavra é deslocada do seu uso comum para construir um efeito de sentido novo.","A semelhança aproxima dois termos por uma característica que eles compartilham, mesmo sendo de naturezas diferentes.","A implicação mútua liga dois termos porque um sugere ou pressupõe o outro dentro de um mesmo contexto cultural ou narrativo.","Identificar se a base da figura é semelhança ou implicação mútua ajuda a nomear corretamente o recurso usado no texto."]'::jsonb,'[["Sentido denotativo","Significado literal, convencional, de dicionário."],["Sentido conotativo","Significado figurado, que depende do contexto."],["Semelhança","Mecanismo que aproxima dois termos por uma característica comum."],["Implicação mútua","Mecanismo em que um termo remete ao outro por proximidade lógica."],["Desvio de sentido","Afastamento do uso convencional de uma palavra ou expressão."]]'::jsonb,'["sentido literal","sentido figurado","denotação","conotação","semelhança","implicação mútua","contexto","figura de linguagem","desvio semântico"]'::jsonb,'["sentido literal segue o uso convencional da palavra","sentido figurado depende do contexto para ser interpretado","semelhança e implicação mútua são as duas bases mais comuns das figuras de linguagem","a mesma palavra pode ter sentido literal em um texto e figurado em outro"]'::jsonb,30)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('portugues-7','portugues','Módulo 7','Figuras de semelhança','O módulo detalha as figuras de linguagem baseadas em semelhança. Comparação aproxima dois termos de forma explícita, usando conectores como ''como'' ou ''tal qual''. Metáfora faz a mesma aproximação sem conector, substituindo um termo por outro. Catacrese é uma metáfora tão usada no dia a dia que perdeu a percepção de ser figurada. Sinestesia mistura sensações captadas por sentidos diferentes (visão, audição, tato) numa só expressão. Personificação atribui características de seres vivos a seres ou objetos inanimados.','["Comparação usa um conector explícito para ligar os dois termos aproximados.","Metáfora aproxima dois termos sem conector, fundindo os sentidos diretamente.","Catacrese é uma metáfora tão consolidada pelo uso que deixou de ser percebida como figura, como em ''braço da cadeira''.","Sinestesia combina percepções de sentidos diferentes, como som e cor, numa mesma imagem.","Personificação (ou prosopopeia) dá ações ou sentimentos humanos a algo que não é humano."]'::jsonb,'[["Comparação","Aproximação explícita entre dois termos por meio de conector."],["Metáfora","Substituição de um termo por outro com base em semelhança, sem conector."],["Catacrese","Metáfora popularizada que perdeu a percepção de ser figura de linguagem."],["Sinestesia","Mistura de sensações de diferentes órgãos do sentido em uma expressão."],["Personificação","Atribuição de qualidades humanas a seres inanimados ou abstratos."]]'::jsonb,'["comparação","metáfora","catacrese","sinestesia","personificação","prosopopeia","conector comparativo","semelhança","substituição"]'::jsonb,'["a comparação sempre usa um termo comparativo explícito","a metáfora não precisa de conector para funcionar","catacrese é uma metáfora desgastada pelo uso cotidiano","sinestesia mistura sentidos diferentes em uma única imagem","personificação trata algo não humano como se tivesse vida ou vontade"]'::jsonb,40)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('portugues-11','portugues','Módulo 11','Inferência de temas','O módulo trabalha a diferença entre figuras e temas em textos verbais, não verbais e multimodais. Figuras são elementos concretos do texto, muitas vezes expressos por substantivos concretos; temas são noções abstratas que ficam, em geral, implícitas, sendo expressas por substantivos abstratos. Inferir o tema de um texto narrativo ou imagético exige levantar hipóteses de leitura apoiadas em pistas do próprio texto e no repertório de mundo do leitor, sempre considerando o conjunto das figuras combinadas, nunca uma figura isolada.','["Figuras são elementos concretos do texto; temas são noções abstratas, geralmente implícitas.","O tema de um texto emerge da combinação de várias figuras, e não da análise isolada de uma única figura.","A inferência de temas depende de hipóteses de leitura baseadas em pistas textuais e no repertório de mundo do leitor.","Textos não verbais e multimodais (como fotografias e campanhas publicitárias) também veiculam temas implícitos por meio de suas figuras visuais.","Comparar diferentes textos sobre o mesmo acontecimento ajuda a perceber como a escolha das figuras pode sugerir posicionamentos distintos sobre um mesmo tema."]'::jsonb,'[["Figura (no sentido temático)","Elemento concreto do texto, muitas vezes ligado a um substantivo concreto."],["Tema","Noção abstrata que o texto sugere, geralmente de forma implícita."],["Inferência","Conclusão obtida a partir de pistas do texto e de conhecimento prévio do leitor."],["Texto multimodal","Texto que combina mais de um modo de linguagem, como imagem e palavra."],["Hipótese de leitura","Interpretação provisória construída e testada à medida que se lê o texto."]]'::jsonb,'["figura concreta","tema abstrato","inferência","texto multimodal","fotojornalismo","hipótese de leitura","repertório de mundo","posicionamento implícito"]'::jsonb,'["figuras são concretas e temas são abstratos","o tema de um texto resulta da combinação das figuras, não de uma figura isolada","imagens e fotografias também podem veicular temas implícitos","a escolha de quais figuras mostrar pode sugerir diferentes posicionamentos sobre o mesmo fato"]'::jsonb,50)
