insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('fisica-newton','fisica','Módulo 1','Newton e forças','A revisão de Física cobre conversão de unidades, leis de Newton, força resultante, peso, normal, atrito, plano inclinado e equilíbrio por torque. A ideia central é identificar forças, calcular resultantes e relacionar massa, aceleração e força.','["Para converter m/s para km/h, multiplique por 3,6; para converter km/h para m/s, divida por 3,6.","A Primeira Lei de Newton diz que o movimento só muda se houver força resultante não nula.","A Segunda Lei usa F = m.a para relacionar força resultante, massa e aceleração.","Peso é calculado por P = m.g; normal é a força da superfície sobre o corpo.","Atrito se opõe à tendência de escorregamento; torque depende de força e distância ao apoio."]'::jsonb,'[["Força resultante","Soma vetorial das forças que atuam em um corpo."],["Inércia","Tendência de manter repouso ou movimento uniforme."],["Peso","Força gravitacional sobre um corpo."],["Normal","Força perpendicular exercida por uma superfície."],["Torque","Efeito de rotação produzido por uma força."]]'::jsonb,'["inércia","força resultante","F = m.a","peso","normal","atrito","torque","ação e reação","plano inclinado","alavanca"]'::jsonb,'["20 m/s equivale a 72 km/h","massa de 70 kg pesa cerca de 700 N na Terra","ação e reação atuam em corpos diferentes","alicates são alavancas","sem atrito no plano inclinado atuam peso e normal"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('fisica-calculos','fisica','Módulo 2','Cálculos e equilíbrio','Nos exercícios dissertativos, é importante mostrar o cálculo completo: converter unidades, aplicar F = m.a, calcular peso, somar forças opostas, usar atrito Fat = μ.N, aplicar equilíbrio de torques e calcular velocidade média.','["Em forças opostas na mesma direção, subtraia intensidades e mantenha o sentido da maior força.","Velocidade média é distância dividida pelo tempo, com unidades compatíveis.","Com velocidade constante, a força resultante é zero.","O coeficiente de atrito pode ser calculado por μ = Fat/N.","No equilíbrio, os torques horário e anti-horário devem se compensar."]'::jsonb,'[["Velocidade média","Razão entre deslocamento/distância e intervalo de tempo."],["Coeficiente de atrito","Número que relaciona atrito e força normal."],["Equilíbrio","Situação em que força resultante e torque resultante podem ser nulos."],["Sentido da força","Direção orientada para onde a força atua."],["Unidade SI","Sistema Internacional, como metro, segundo e newton."]]'::jsonb,'["velocidade média","conversão","forças opostas","coeficiente de atrito","equilíbrio","torque","newton","massa","aceleração","gravidade"]'::jsonb,'["360 km/h equivale a 100 m/s","1800 m em 300 s equivale a 6 m/s","60 kg com g 9,8 pesa 588 N","forças 15 N e 5 N opostas resultam em 10 N","μ = 0,2 quando Fat 4 N e N 20 N"]'::jsonb,10)
