insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('circuitos-basico','circuitos','Módulo 1','Circuito elétrico','Um circuito elétrico precisa de fonte de energia, condutores e componente consumidor. Para a corrente circular, o caminho deve estar fechado. GND é a referência negativa; curto-circuito é um caminho de resistência muito baixa que pode danificar fios, componentes e placas.','["Circuito fechado permite passagem de corrente.","Circuito aberto interrompe a corrente.","Fonte, condutores e carga formam o circuito básico.","GND funciona como referência negativa.","Curto-circuito é perigoso por gerar corrente alta."]'::jsonb,'[["Corrente","Fluxo de cargas elétricas."],["Tensão","Diferença de potencial elétrico."],["GND","Referência negativa do circuito."],["Carga","Componente que consome energia."],["Curto-circuito","Caminho de resistência muito baixa."]]'::jsonb,'["corrente","tensão","fonte","caminho fechado","GND","curto-circuito","carga","condutores","Arduino","porta"]'::jsonb,'["circuito aberto não funciona","curto pode queimar placa","GND é referência negativa","corrente precisa de caminho fechado","carga pode ser LED motor ou sensor"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('circuitos-led','circuitos','Módulo 2','LEDs e resistores','LED possui polaridade: anodo positivo e catodo negativo. Ele deve ser ligado com resistor em série, pois o resistor limita a corrente e protege tanto o LED quanto a porta do Arduino.','["LED conduz em apenas um sentido.","Anodo é o terminal positivo; catodo é o negativo.","Resistor limita corrente.","Resistência é medida em ohms.","Sem resistor, o LED pode queimar."]'::jsonb,'[["Anodo","Terminal positivo do LED."],["Catodo","Terminal negativo do LED."],["Resistor","Componente que limita corrente."],["Ohm","Unidade de resistência elétrica."],["Série","Ligação em sequência no mesmo caminho."]]'::jsonb,'["LED","resistor","anodo","catodo","polaridade","série","ohm","corrente","proteção","código de cores"]'::jsonb,'["LED sem resistor é erro","resistor protege componentes","LED invertido não acende","anodo vai no positivo","catodo vai no negativo"]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('circuitos-protoboard','circuitos','Módulo 3','Jumpers e protoboard','Jumpers conectam pontos do circuito. A protoboard permite montar circuitos sem solda, facilitando testes e correções. Organização evita erros como inverter GND e 5V, trocar polaridade de LED ou ligar sensores nos pinos errados.','["Jumpers são fios de conexão.","Protoboard permite testes sem solda.","Organização reduz erros de montagem.","Linhas internas da protoboard conectam pontos específicos.","Identificar trilhas evita conexões erradas."]'::jsonb,'[["Jumper","Fio usado para conexão."],["Protoboard","Placa de montagem sem solda."],["Trilha","Conjunto de pontos conectados internamente."],["Montagem","Organização física do circuito."],["Teste","Verificação antes da montagem definitiva."]]'::jsonb,'["jumpers","protoboard","sem solda","organização","trilhas","conexões","Arduino","5V","GND","pinos"]'::jsonb,'["protoboard facilita correções","jumpers conectam Arduino e componentes","organização evita inversão","sem solda favorece protótipo","pinos errados geram falhas"]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('circuitos-ultrassonico','circuitos','Módulo 4','Sensor ultrassônico','O sensor ultrassônico mede distância emitindo um pulso sonoro e calculando o tempo até o eco retornar. Os pinos principais são VCC, GND, TRIG e ECHO. Projetos comuns incluem lixeira automática, robô desvia-obstáculos e medidor de distância.','["VCC alimenta o sensor.","GND liga ao negativo.","TRIG dispara o pulso sonoro.","ECHO recebe o retorno.","A distância depende do tempo de ida e volta do som."]'::jsonb,'[["VCC","Pino de alimentação positiva."],["TRIG","Pino que dispara o pulso."],["ECHO","Pino que recebe o sinal de retorno."],["Eco","Retorno da onda sonora."],["Distância","Medida calculada pelo tempo do som."]]'::jsonb,'["sensor ultrassônico","VCC","GND","TRIG","ECHO","distância","eco","onda sonora","Arduino","tempo"]'::jsonb,'["TRIG dispara","ECHO recebe","VCC alimenta","GND fecha referência","inverter TRIG e ECHO é erro comum"]'::jsonb,30)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('circuitos-transistores','circuitos','Módulo 5','Transistores','Transistores funcionam como chaves eletrônicas, controlando a passagem de corrente. Em circuitos maiores, sinais pequenos podem controlar cargas maiores. A lógica digital usa estados ligado/desligado, verdadeiro/falso, 0 e 1.','["Transistor pode atuar como chave.","Sinal pequeno pode controlar corrente maior.","Ligado e desligado representam estados digitais.","Processadores têm muitos transistores microscópicos.","A lógica binária depende desses estados."]'::jsonb,'[["Transistor","Componente semicondutor que controla corrente."],["Chave eletrônica","Controle liga/desliga por sinal elétrico."],["Binário","Sistema baseado em 0 e 1."],["Sinal","Informação elétrica de controle."],["Carga","Elemento controlado no circuito."]]'::jsonb,'["transistor","chave eletrônica","corrente","sinal","carga","0 e 1","lógica digital","ligado","desligado","processador"]'::jsonb,'["transistores controlam passagem de corrente","processadores têm bilhões de transistores","0 e 1 representam estados","sinal pequeno controla carga maior","lógica digital usa verdadeiro e falso"]'::jsonb,40)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('circuitos-processadores','circuitos','Módulo 6','Processadores','Processadores são fabricados principalmente a partir do silício, material semicondutor. O silício é purificado, transformado em wafers e recebe camadas de circuitos microscópicos por processos como fotolitografia. Miniaturização aumenta capacidade e eficiência.','["Silício é material base dos chips.","Wafers são discos usados na fabricação.","Fotolitografia cria padrões microscópicos.","Camadas formam circuitos complexos.","Transistores menores ajudam desempenho e consumo."]'::jsonb,'[["Silício","Semicondutor usado em chips."],["Wafer","Disco de silício usado como base."],["Fotolitografia","Processo de gravação de padrões microscópicos."],["Miniaturização","Redução do tamanho dos componentes."],["Chip","Circuito integrado."]]'::jsonb,'["silício","wafer","fotolitografia","camadas","chip","processador","miniaturização","transistores","semicondutor","eficiência"]'::jsonb,'["silício vem da areia após purificação","wafer é base do chip","fotolitografia cria circuitos","miniaturização reduz consumo","mais transistores podem aumentar processamento"]'::jsonb,50)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('calc-estrutura','calculadoras','Módulo 1','Estrutura do app','O app de cálculos contábeis possui tela inicial, calculadora, campos de entrada, botões, área de resultado e funções para organizar cálculos. HTML estrutura, CSS estiliza e JavaScript dá funcionamento.','["HTML organiza menu, telas, formulário e resultados.","CSS define layout, cores e alinhamento.","JavaScript troca telas, lê campos e calcula.","Funções separam responsabilidades.","IDs conectam HTML e JavaScript."]'::jsonb,'[["HTML","Estrutura da página."],["CSS","Aparência e layout."],["JavaScript","Funcionamento e lógica."],["Função","Bloco nomeado de código."],["Tela","Parte exibida da aplicação."]]'::jsonb,'["HTML","CSS","JavaScript","tela inicial","calculadora","campos","botões","resultados","funções","layout"]'::jsonb,'["HTML cria estrutura","CSS organiza visual","JS calcula e atualiza","funções separam tarefas","ID permite localizar elemento"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('calc-html','calculadoras','Módulo 2','HTML e IDs','A prova pode pedir interpretação de elementos como div.app, div.menu, div#home, div#calculadora, input#salario, select#dependentes, select#pensao, span#valorIr e button#button. O id é essencial para o JavaScript encontrar o elemento.','["input recebe valores digitados.","select permite escolher opções.","span exibe resultado.","button dispara ação.","id precisa bater exatamente com o usado no JS."]'::jsonb,'[["input","Campo de entrada."],["select","Lista de seleção."],["span","Elemento inline usado para texto ou resultado."],["button","Botão clicável."],["id","Identificador único."]]'::jsonb,'["input","select","span","button","id","salario","dependentes","pensao","valorIr","formulário"]'::jsonb,'["id conecta HTML ao JS","input#salario recebe salário bruto","select#dependentes guarda quantidade","span#valorIr exibe IR","button pode acionar cálculo"]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('calc-css','calculadoras','Módulo 3','CSS e layout','CSS controla o visual: .app, .menu, .home, .calc, .box, .resultado e #campo-pensao. A classe .calc pode começar com display none e virar flex pelo JavaScript. #campo-pensao fica oculto até a opção de pensão ser escolhida.','["display none esconde um elemento.","display flex ajuda a organizar layout.","Classes são reutilizáveis; ids são únicos.","Padding, largura e cores definem cartões.","JS pode alterar style.display."]'::jsonb,'[["display","Propriedade que controla exibição."],["flex","Modo de layout flexível."],["classe","Seletor CSS reutilizável."],["seletor","Forma de escolher elementos no CSS."],["padding","Espaço interno."]]'::jsonb,'["CSS","display none","display flex","classe","id","layout","menu","box","resultado","campo-pensao"]'::jsonb,'[".calc pode ficar oculta","#campo-pensao começa oculto","flex centraliza e distribui","classe começa com ponto","id começa com cerquilha"]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('calc-dom','calculadoras','Módulo 4','DOM e valores','DOM é a representação da página que o JavaScript acessa. getElementById localiza elementos, value lê campos, Number converte texto em número, innerHTML altera conteúdo e toFixed(2) formata com duas casas decimais.','["document.getElementById busca pelo id.","value lê o valor de input/select.","Number evita cálculo como texto.","innerHTML troca conteúdo exibido.","toFixed(2) padroniza valores monetários."]'::jsonb,'[["DOM","Representação manipulável da página."],["value","Valor atual de um campo."],["innerHTML","Conteúdo interno de um elemento."],["Number","Conversão para número."],["toFixed","Formatação de casas decimais."]]'::jsonb,'["DOM","getElementById","value","innerHTML","Number","toFixed","salario.value","valorInss","resultado","conversão"]'::jsonb,'["input.value vem como texto","Number converte para cálculo","innerHTML mostra resultado","toFixed(2) mostra duas casas","DOM permite atualizar página"]'::jsonb,30)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('calc-eventos','calculadoras','Módulo 5','Eventos','Eventos fazem a página responder ao usuário. click executa ações ao clicar, change responde a mudança de campo e keydown responde a teclas. O botão calcular precisa estar conectado a um evento de click.','["addEventListener conecta elemento e ação.","click é usado em botões.","change pode mostrar ou esconder campo de pensão.","keydown pode reagir ao Enter.","Sem evento, o botão não chama a função."]'::jsonb,'[["Evento","Acontecimento capturado pelo JS."],["click","Clique do usuário."],["change","Mudança de valor."],["keydown","Tecla pressionada."],["callback","Função executada pelo evento."]]'::jsonb,'["evento","addEventListener","click","change","keydown","botão","calcular","pensao","campo-pensao","função"]'::jsonb,'["click executa cálculo","change mostra campo de pensão","keydown pode usar Enter","sem evento nada acontece","callback roda quando evento ocorre"]'::jsonb,40)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('calc-funcoes','calculadoras','Módulo 6','Funções e cálculos','Funções como abrirHome, abrirCalculadora, calcularINSS, calcularIr(base) e calcular organizam o projeto. A base do IR usa salário bruto menos INSS, dependentes e pensão. O salário líquido desconta INSS, IR e pensão.','["Função evita repetição e organiza código.","calcularINSS usa faixas e condicionais.","calcularIr recebe base como parâmetro.","Dependentes reduzem base do IR, mas não saem diretamente do líquido.","return devolve o valor calculado."]'::jsonb,'[["Parâmetro","Valor recebido pela função."],["return","Valor devolvido pela função."],["Base do IR","Valor usado para calcular imposto."],["Líquido","Salário após descontos efetivos."],["INSS","Desconto previdenciário."]]'::jsonb,'["função","parâmetro","return","calcularINSS","calcularIr","base IR","salário líquido","dependentes","pensão","desconto"]'::jsonb,'["base IR desconta INSS dependentes pensão","líquido desconta INSS IR pensão","dependente não sai direto do líquido","return é necessário","funções separam cálculo"]'::jsonb,50)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('calc-condicionais','calculadoras','Módulo 7','Condicionais','if, else if e else permitem que o programa escolha blocos conforme condições. Em cálculos de INSS e IR, a ordem importa porque o programa executa apenas o primeiro bloco verdadeiro.','["if testa uma condição.","else if testa outra condição se a anterior falhar.","else cobre os demais casos.","A ordem das faixas altera o resultado.","Operadores como >= e <= aparecem em faixas."]'::jsonb,'[["if","Se uma condição for verdadeira."],["else if","Nova condição alternativa."],["else","Caso contrário."],["Condição","Expressão que resulta em verdadeiro ou falso."],["Faixa","Intervalo de valores."]]'::jsonb,'["if","else if","else","condição","faixa","operadores","maior igual","menor igual","IR","INSS"]'::jsonb,'["ordem das condições importa","só um bloco é executado","else cobre resto",">= inclui limite","condicional decide cálculo"]'::jsonb,60)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('calc-erros','calculadoras','Módulo 8','Erros comuns','Erros comuns incluem esquecer Number, digitar id diferente no HTML e JS, usar innerHTML no elemento errado, não chamar função no evento, confundir base do IR com salário bruto e esquecer return em função de cálculo.','["IDs devem ser iguais no HTML e no JS.","Sem Number, soma pode virar concatenação.","Sem return, a função devolve undefined.","Evento mal ligado impede o botão de funcionar.","Base do IR não é igual ao salário bruto."]'::jsonb,'[["Bug","Erro de funcionamento."],["undefined","Valor indefinido no JavaScript."],["concatenação","Junção de textos."],["chamada de função","Uso de nomeDaFuncao()."],["debug","Investigação e correção de erros."]]'::jsonb,'["bug","Number","id errado","innerHTML","evento","return","undefined","base IR","salário bruto","correção"]'::jsonb,'["id errado quebra captura","sem return resultado vira undefined","sem parênteses função não chama","Number evita texto","innerHTML errado mostra no lugar errado"]'::jsonb,70)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('logica-condicional','logica','Módulo 1','if/else','Estrutura condicional é usada quando o programa precisa tomar decisão. Se a condição for verdadeira, executa um bloco; caso contrário, executa outro bloco opcional.','["if testa uma condição.","else executa quando o if falha.","Condições retornam verdadeiro ou falso.","A indentação ajuda leitura.","Blocos usam chaves em JavaScript."]'::jsonb,'[["Condição","Expressão booleana."],["if","Estrutura se."],["else","Caso contrário."],["Bloco","Código entre chaves."],["Booleano","Verdadeiro ou falso."]]'::jsonb,'["if","else","condição","verdadeiro","falso","bloco","decisão","nota","aprovado","recuperação"]'::jsonb,'["nota 6 com nota >= 7 cai no else","if decide fluxo","else é opcional","condição usa comparação","bloco executado depende do teste"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('logica-operadores','logica','Módulo 2','Operadores','Operadores de comparação como >, <, >=, <=, ==, != e === ajudam o programa a comparar valores antes de decidir. É importante não confundir atribuição = com comparação == ou ===.','["> e < comparam maior e menor.",">= e <= incluem o limite.","== compara valor com conversão.","=== compara valor e tipo.","= atribui valor, não compara."]'::jsonb,'[[">","Maior que."],["<","Menor que."],[">=","Maior ou igual."],["==","Igualdade com conversão."],["===","Igualdade estrita."]]'::jsonb,'[">","<",">=","<=","==","!=","===","=","comparação","atribuição"]'::jsonb,'["= não compara","=== é mais estrito",">= inclui limite","!= significa diferente","operadores formam condições"]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('logica-funcoes','logica','Módulo 3','Funções','Funções são blocos de código com nome, criados para organizar o programa e evitar repetição. Uma função pode receber parâmetros e devolver resultado com return.','["function declara uma função.","Parâmetros recebem valores de entrada.","return devolve um resultado.","Chamar função exige parênteses.","Funções ajudam reaproveitamento."]'::jsonb,'[["Função","Bloco de código reutilizável."],["Parâmetro","Entrada da função."],["Argumento","Valor passado na chamada."],["return","Saída da função."],["Chamada","Execução da função."]]'::jsonb,'["função","function","parâmetro","argumento","return","chamada","dobro","calcularMedia","resultado","reutilização"]'::jsonb,'["dobro(8) retorna 16","return devolve valor","parâmetro recebe entrada","função sem chamada não executa","calcularMedia pode receber duas notas"]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('logica-while','logica','Módulo 4','while','while executa um bloco enquanto uma condição for verdadeira. É essencial atualizar a variável de controle dentro do laço para evitar loop infinito.','["while verifica a condição antes de cada repetição.","Contador controla quantas vezes repete.","contador++ aumenta uma unidade.","Sem atualização, o laço pode nunca terminar.","Use while para contagens e repetições condicionais."]'::jsonb,'[["while","Enquanto."],["Loop","Repetição."],["Contador","Variável de controle."],["Incremento","Aumento do valor."],["Loop infinito","Repetição sem fim."]]'::jsonb,'["while","loop","contador","incremento","contador++","condição","repetição","loop infinito","console.log","controle"]'::jsonb,'["contador controla repetição","sem contador++ pode travar","while(contador <= 3) repete até 3","contador de 1 a 5 mostra cinco valores","condição falsa encerra laço"]'::jsonb,30)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('logica-bugs','logica','Módulo 5','Análise de bugs','Erros comuns incluem esquecer chaves, esquecer return, usar = no lugar de comparação, não chamar função com parênteses e criar while sem atualizar a variável.','["Leia o erro e localize a linha provável.","Confira chaves e parênteses.","Diferencie = de comparação.","Verifique se a função foi chamada.","Em while, procure atualização da variável."]'::jsonb,'[["Bug","Erro no programa."],["Sintaxe","Forma correta da linguagem."],["Lógica","Raciocínio do código."],["Parênteses","Usados em chamadas e condições."],["Chaves","Delimitam blocos."]]'::jsonb,'["bug","erro","chaves","return","=","===","parênteses","while","contador","debug"]'::jsonb,'["função sem parênteses não é chamada","return esquecido perde resultado","while sem incremento é infinito","chave faltando quebra sintaxe","usar = em if é bug comum"]'::jsonb,40)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('logica-pratica','logica','Módulo 6','Prática de código','Para responder questões de código, leia variáveis iniciais, simule a execução linha por linha, observe condições, acompanhe alterações de contador e verifique o valor retornado por funções.','["Simule valores em uma tabela mental.","Acompanhe cada mudança de variável.","Veja onde console.log é chamado.","Em funções, siga até o return.","Em provas, explique o raciocínio, não apenas o resultado."]'::jsonb,'[["Simulação","Execução mental do código."],["Variável","Espaço que guarda valor."],["console.log","Comando que exibe no console."],["Raciocínio","Explicação passo a passo."],["Resultado","Valor final produzido."]]'::jsonb,'["simulação","variável","console.log","passo a passo","resultado","return","contador","média","notas","execução"]'::jsonb,'["explicar passo a passo ajuda nas dissertativas","console.log mostra valor","return pode ser usado em outra variável","variáveis mudam ao longo do código","média de 6 e 8 é 7"]'::jsonb,50)
