insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('ingles-sinonimia','ingles','Módulo 1','Synonyms','Sinonímia em Inglês envolve reconhecer palavras com sentido semelhante dentro de um contexto. Nem sempre dois sinônimos podem ser trocados em qualquer frase: é preciso observar formalidade, colocação, intensidade e situação de uso.','["Synonyms são palavras de sentido parecido.","Contexto decide qual sinônimo fica natural.","Big, large e huge não têm a mesma intensidade.","Begin e start são parecidos, mas podem variar em formalidade.","Em prova, leia a frase inteira antes de escolher o sinônimo."]'::jsonb,'[["Synonym","Palavra com significado semelhante."],["Meaning","Sentido de uma palavra."],["Context","Situação em que a palavra aparece."],["Formal","Mais adequado a situações formais."],["Informal","Mais comum em conversa cotidiana."]]'::jsonb,'["synonym","meaning","context","formal","informal","big","large","huge","begin","start"]'::jsonb,'["synonym means similar meaning","context changes word choice","huge is stronger than big","begin can sound more formal than start","choose the word that fits the sentence"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('ingles-emergencias','ingles','Módulo 2','Emergencies and disasters','Este módulo reúne vocabulário para situações de emergência e desastres naturais. É importante reconhecer palavras como earthquake, flood, fire, storm, landslide, drought, rescue, help, shelter e emergency call.','["Emergency é uma situação de risco que exige ação rápida.","Natural disasters incluem earthquake, flood, storm, drought e landslide.","Rescue significa resgate.","Shelter é abrigo.","Call for help é uma expressão útil em emergências."]'::jsonb,'[["Earthquake","Terremoto."],["Flood","Enchente/inundação."],["Fire","Incêndio."],["Storm","Tempestade."],["Shelter","Abrigo."]]'::jsonb,'["emergency","earthquake","flood","fire","storm","drought","landslide","rescue","shelter","help"]'::jsonb,'["earthquake means terremoto","flood means enchente","shelter means abrigo","rescue means resgate","call for help is used in emergencies"]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('ingles-past-tenses','ingles','Módulo 3','Past tenses','Past tenses expressam ações no passado. Simple Past descreve ações concluídas; Past Continuous descreve ações em progresso no passado; Past Perfect indica uma ação anterior a outra também passada.','["Simple Past usa verbos regulares com -ed ou formas irregulares.","Did aparece em perguntas e negativas no Simple Past.","Past Continuous usa was/were + verbo com -ing.","Past Perfect usa had + past participle.","Use marcadores como yesterday, last week, while e before para entender o tempo verbal."]'::jsonb,'[["Simple Past","Ação concluída no passado."],["Past Continuous","Ação em andamento no passado."],["Past Perfect","Ação anterior a outra ação passada."],["Regular verb","Verbo que forma passado com -ed."],["Irregular verb","Verbo com forma própria no passado."]]'::jsonb,'["simple past","past continuous","past perfect","did","was","were","had","regular verbs","irregular verbs","past participle"]'::jsonb,'["simple past shows finished actions","past continuous uses was or were plus ing","past perfect uses had plus past participle","did is used in questions and negatives","yesterday often indicates past"]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('ingles-plural-nouns','ingles','Módulo 4','Plural of nouns','O plural dos substantivos em Inglês costuma receber -s, mas há regras especiais. Palavras terminadas em -s, -x, -ch, -sh recebem -es; consoante + y vira -ies; alguns substantivos são irregulares, como child/children e man/men.','["A regra geral do plural é adicionar -s.","Bus vira buses; box vira boxes.","City vira cities quando há consoante + y.","Boy vira boys porque há vogal + y.","Irregular plurals precisam ser memorizados."]'::jsonb,'[["Noun","Substantivo."],["Plural","Forma para mais de um."],["Regular plural","Plural formado por regra padrão."],["Irregular plural","Plural com forma própria."],["Ending","Final da palavra."]]'::jsonb,'["plural","noun","s","es","ies","irregular plural","child children","man men","city cities","box boxes"]'::jsonb,'["most nouns add s","box becomes boxes","city becomes cities","child becomes children","man becomes men"]'::jsonb,30)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('ingles-countable','ingles','Módulo 5','Countable and uncountable nouns','Countable nouns podem ser contados e têm singular/plural, como apple/apples. Uncountable nouns indicam massa, líquido, ideia ou categoria geral e normalmente não usam plural direto, como water, rice, money e information.','["Countable nouns usam a/an no singular.","Uncountable nouns não usam a/an diretamente.","Use much com uncountable e many com countable.","Use some/any com ambos, dependendo da frase.","Para contar uncountable, use expressões como a bottle of water ou a piece of information."]'::jsonb,'[["Countable","Substantivo contável."],["Uncountable","Substantivo incontável."],["Many","Muitos/muitas para contáveis."],["Much","Muito/muita para incontáveis."],["Piece of","Expressão para contar uma unidade de algo incontável."]]'::jsonb,'["countable","uncountable","many","much","some","any","a bottle of","a piece of","water","information"]'::jsonb,'["apple is countable","water is uncountable","many is used with countable nouns","much is used with uncountable nouns","information is usually uncountable"]'::jsonb,40)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('mat-a-eq2','matematica-a','Módulo 1','Equações do 2º Grau','Toda equação da forma ax² + bx + c = 0 (com a ≠ 0) é resolvida pela fórmula resolutiva. O discriminante, ou delta, define o número de raízes reais, e as relações de Girard conectam essas raízes aos coeficientes da equação.','["Se delta > 0: duas raízes reais e distintas.","Se delta = 0: duas raízes reais e iguais.","Se delta < 0: não possui raízes reais.","Soma das raízes por Girard: -b/a.","Produto das raízes por Girard: c/a."]'::jsonb,'[["Discriminante","Representado por delta (b² - 4ac), define a quantidade de raízes reais."],["Relações de Girard","Fórmulas que relacionam a soma e o produto das raízes com os coeficientes da equação."],["Forma Fatorada","A expressão a(x - x1)(x - x2) = 0, onde x1 e x2 são as raízes da equação."],["Equação Biquadrada","Equação escrita na forma ax^4 + bx² + c = 0."],["Equação Irracional","Equação cuja incógnita aparece dentro de um radical."]]'::jsonb,'["equação do 2º grau","fórmula resolutiva","discriminante","raízes reais","soma","produto","equação biquadrada","equação racional","equação irracional"]'::jsonb,'["O valor do discriminante indica o número de raízes reais de uma equação.","A soma das raízes de uma equação do 2º grau é obtida por -b/a.","O produto das raízes de uma equação do 2º grau é obtido por c/a.","Uma equação irracional possui a incógnita dentro do radicando.","A forma fatorada de um trinômio do 2º grau depende do conhecimento prévio de suas raízes."]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('mat-b-angulos','matematica-b','Módulo 1','Ângulos e Triângulos','Estudo das classificações dos ângulos e suas relações, como complementares, suplementares e opostos pelo vértice. Nos triângulos, analisa-se a soma dos ângulos internos e o teorema do ângulo externo.','["Ângulo reto mede 90º, agudo é menor que 90º e obtuso é maior que 90º.","Ângulos complementares somam 90º; suplementares somam 180º.","Ângulos opostos pelo vértice possuem a mesma medida.","A soma dos ângulos internos de um triângulo é sempre 180º.","A medida do ângulo externo é igual à soma dos dois internos não adjacentes a ele."]'::jsonb,'[["Ângulo raso","Ângulo obtido por duas semirretas opostas; mede 180º."],["Bissetriz","Semirreta que divide um ângulo em outros dois congruentes."],["Triângulo isósceles","Triângulo que possui dois lados iguais e ângulos da base congruentes."],["Ângulos alternos internos","Em retas paralelas cortadas por transversal, são ângulos congruentes em lados opostos da transversal."],["Retas Concorrentes","Retas que se cruzam em um único ponto, formando ângulos opostos pelo vértice."]]'::jsonb,'["ângulo agudo","ângulo obtuso","ângulos complementares","ângulos suplementares","teorema angular de tales","retas paralelas","triângulo equilátero"]'::jsonb,'["Dois ângulos adjacentes podem ser consecutivos e suplementares.","Em um triângulo equilátero, cada ângulo interno mede exatamente 60º.","Em um triângulo retângulo, a soma dos dois ângulos agudos é sempre 90º.","Ângulos colaterais internos em retas paralelas são sempre suplementares.","Ângulos correspondentes em retas paralelas têm a mesma medida."]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('mat-b-poligonos','matematica-b','Módulo 2','Polígonos e Circunferência','Propriedades dos polígonos convexos e regulares, incluindo cálculo de diagonais e ângulos. O módulo também trata de relações entre arcos e ângulos na circunferência.','["Soma dos ângulos internos: (n - 2) * 180º.","Soma dos ângulos externos de um polígono convexo é sempre 360º.","Número de diagonais: d = n(n - 3) / 2.","O ângulo inscrito na circunferência vale metade do arco correspondente.","Polígono regular é equilátero e equiângulo."]'::jsonb,'[["Polígono Convexo","Polígono onde qualquer segmento ligando dois de seus pontos internos fica inteiramente dentro da figura."],["Ângulo Central","Ângulo cujo vértice está no centro da circunferência."],["Ângulo Inscrito","Ângulo cujo vértice é um ponto pertencente à circunferência."],["Ângulo de Segmento","Ângulo formado por uma reta secante e uma reta tangente à circunferência."],["Polígono Regular","Polígono que possui todos os lados congruentes e todos os ângulos congruentes."]]'::jsonb,'["polígono regular","soma dos ângulos internos","soma dos ângulos externos","diagonais","circunferência","ângulo inscrito","arco de circunferência"]'::jsonb,'["O número de diagonais de um polígono depende diretamente do seu número de lados.","A soma dos ângulos externos de qualquer polígono convexo é sempre 360º.","Para calcular a medida de um ângulo interno em um polígono regular, divide-se a soma dos internos pelo número de lados.","A medida do arco correspondente a um ângulo central é idêntica à do próprio ângulo.","Um ângulo de segmento mede a metade da medida do arco correspondente."]'::jsonb,10)
