insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('arte-renascimento-barroco','arte','Módulo 1','Renascentismo e Barroco','Uma análise de dois dos maiores movimentos da história da arte. O Renascimento foca no antropocentrismo, na simetria e na razão. O Barroco foca na emoção, no exagero, no conflito espiritual e na iluminação dramática.','["O Renascimento valoriza a razão, a proporção exata e o resgate da cultura greco-romana.","Perspectiva linear foi uma das grandes inovações técnicas renascentistas.","O Barroco surgiu no contexto da Contrarreforma para atrair fiéis pelas emoções.","Técnica do chiaroscuro, contraste intenso entre luz e sombra, é marca do Barroco.","Enquanto o Renascimento é estático e equilibrado, o Barroco é dinâmico e dramático."]'::jsonb,'[["Antropocentrismo","Visão de mundo renascentista que coloca o homem como o centro de tudo."],["Chiaroscuro","Técnica de pintura focada no contraste drástico entre claro e escuro, criando ilusão de volume."],["Contrarreforma","Movimento católico que impulsionou o Barroco como ferramenta de persuasão religiosa."],["Perspectiva Linear","Método matemático utilizado no Renascimento para criar a ilusão de profundidade em superfícies planas."],["Teocentrismo","A ideia de Deus no centro de tudo, que o Renascimento contrapôs e o Barroco tentou resgatar de forma emocional."]]'::jsonb,'["renascimento","barroco","antropocentrismo","chiaroscuro","emoção e drama","harmonia e proporção","contrarreforma"]'::jsonb,'["Leonardo da Vinci e Michelangelo são representantes icônicos do Renascimento.","Caravaggio é considerado um dos maiores mestres do chiaroscuro no Barroco.","A arte renascentista buscava o equilíbrio perfeito e formas geométricas limpas.","O Barroco utiliza composições diagonais para gerar sensação de movimento e tensão.","A Igreja Católica foi a principal financiadora da arte barroca na Europa."]'::jsonb,0)
