insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('bio-interacoes','biologia','Módulo 1','Interações ecológicas','Interações ecológicas são relações entre seres vivos. Podem ocorrer entre indivíduos da mesma espécie ou de espécies diferentes, e podem ser harmônicas, quando ninguém é prejudicado, ou desarmônicas, quando pelo menos um organismo sofre prejuízo.','["Relações intraespecíficas ocorrem na mesma espécie.","Relações interespecíficas ocorrem entre espécies diferentes.","Mutualismo beneficia os dois organismos.","Predatismo beneficia o predador e prejudica a presa.","Competição pode ocorrer por alimento, território, luz ou parceiros."]'::jsonb,'[["Mutualismo","Relação em que ambos se beneficiam."],["Comensalismo","Um se beneficia e o outro não é prejudicado."],["Predatismo","Um organismo captura e consome outro."],["Parasitismo","Parasita se beneficia prejudicando o hospedeiro."],["Competição","Disputa por recursos."]]'::jsonb,'["interações ecológicas","intraespecífica","interespecífica","mutualismo","comensalismo","predatismo","parasitismo","competição","harmônica","desarmônica"]'::jsonb,'["mutualismo beneficia ambos","predatismo envolve presa e predador","parasitismo prejudica hospedeiro","competição disputa recursos","comensalismo não prejudica o outro organismo"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('bio-taxonomia','biologia','Módulo 2','Taxonomia e filogenética','Taxonomia classifica os seres vivos em categorias hierárquicas. Sistemática filogenética busca entender relações evolutivas e parentesco entre organismos, usando características compartilhadas e ancestralidade comum.','["Categorias principais: domínio, reino, filo, classe, ordem, família, gênero e espécie.","Espécie é a unidade básica de classificação.","Nome científico usa gênero e espécie.","Filogenia representa parentesco evolutivo.","Cladogramas mostram hipóteses de ancestralidade comum."]'::jsonb,'[["Taxonomia","Área que identifica, nomeia e classifica seres vivos."],["Sistemática","Estudo da diversidade e das relações evolutivas."],["Filogenia","História evolutiva de um grupo."],["Cladograma","Diagrama de parentesco evolutivo."],["Espécie","Unidade básica de classificação biológica."]]'::jsonb,'["taxonomia","sistemática","filogenética","domínio","reino","espécie","gênero","nome científico","cladograma","ancestral comum"]'::jsonb,'["espécie é unidade básica","nome científico usa gênero e espécie","cladograma mostra parentesco","filogenia estuda história evolutiva","taxonomia organiza seres vivos"]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('bio-monera','biologia','Módulo 3','Reino Monera','O Reino Monera inclui organismos procariontes, como bactérias e cianobactérias. Eles não possuem núcleo verdadeiro nem organelas membranosas e podem ter grande diversidade metabólica e ecológica.','["Procariontes não possuem núcleo delimitado por membrana.","Bactérias têm DNA no nucleoide.","Parede celular bacteriana geralmente contém peptidoglicano.","Podem ser autotróficas ou heterotróficas.","Algumas causam doenças, mas muitas são importantes para decomposição, produção de alimentos e ciclos biogeoquímicos."]'::jsonb,'[["Procarionte","Célula sem núcleo verdadeiro."],["Nucleoide","Região onde fica o DNA bacteriano."],["Bactéria","Organismo unicelular procarionte."],["Cianobactéria","Procarionte fotossintetizante."],["Peptidoglicano","Componente comum da parede bacteriana."]]'::jsonb,'["Monera","bactéria","cianobactéria","procarionte","nucleoide","parede celular","peptidoglicano","autotrófico","heterotrófico","decomposição"]'::jsonb,'["bactérias são procariontes","procariontes não têm núcleo verdadeiro","cianobactérias fazem fotossíntese","nucleoide contém DNA","muitas bactérias são úteis"]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('bio-virus','biologia','Módulo 4','Vírus','Vírus são entidades acelulares formadas por material genético envolto por cápside, podendo ter envelope. Eles não possuem metabolismo próprio e dependem de células hospedeiras para se replicar.','["Vírus são acelulares.","Possuem DNA ou RNA como material genético.","Cápside é a estrutura proteica que protege o material genético.","São parasitas intracelulares obrigatórios.","Só se replicam dentro de células hospedeiras."]'::jsonb,'[["Acelular","Não formado por célula."],["Cápside","Camada proteica do vírus."],["Envelope","Membrana externa presente em alguns vírus."],["Hospedeiro","Organismo ou célula infectada."],["Replicação","Produção de novas partículas virais."]]'::jsonb,'["vírus","acelular","DNA","RNA","cápside","envelope","hospedeiro","parasita intracelular obrigatório","replicação","infecção"]'::jsonb,'["vírus não têm metabolismo próprio","vírus precisam de célula hospedeira","cápside protege material genético","vírus podem ter DNA ou RNA","alguns vírus possuem envelope"]'::jsonb,30)
