insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('bio-doencas-virais','biologia','Módulo 5','Doenças virais','Doenças causadas por vírus dependem da entrada do vírus no organismo e da infecção de células hospedeiras. Prevenção pode envolver vacinação, higiene, controle de vetores, isolamento e uso de medidas de proteção conforme a transmissão.','["Vacinas estimulam resposta imunológica preventiva.","Algumas viroses são transmitidas por gotículas respiratórias.","Outras dependem de vetores, como mosquitos.","Antibióticos não tratam vírus; eles agem contra bactérias.","Prevenção depende do modo de transmissão."]'::jsonb,'[["Virose","Doença causada por vírus."],["Vacina","Método preventivo que estimula imunidade."],["Vetor","Organismo que transmite agente infeccioso."],["Imunidade","Capacidade de defesa do organismo."],["Transmissão","Forma de passagem do agente infeccioso."]]'::jsonb,'["doença viral","virose","vacina","imunidade","vetor","transmissão","gotículas","higiene","prevenção","antibiótico"]'::jsonb,'["antibióticos não combatem vírus","vacinas ajudam na prevenção","mosquitos podem ser vetores","higiene reduz transmissão","prevenção depende da forma de transmissão"]'::jsonb,40)
