insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('geo-interior-terra','geografia','Módulo 5','Interior da Terra','O planeta é organizado em camadas concêntricas que vão da crosta terrestre, mais externa e fina, até o núcleo interno, no centro do planeta, passando pelo manto superior, manto inferior e núcleo externo. Paralelamente, a história geológica da Terra é dividida em eras (Pré-Cambriana, Paleozoica, Mesozoica e Cenozoica), cada uma marcada por eventos como a formação de cadeias de montanhas, o surgimento de novos grupos de seres vivos e mudanças na configuração dos continentes.','["A estrutura interna da Terra é dividida em crosta, manto superior, manto inferior, núcleo externo e núcleo interno.","As eras geológicas (Pré-Cambriana, Paleozoica, Mesozoica e Cenozoica) organizam a história da Terra em grandes intervalos de tempo.","Eventos como o surgimento de dinossauros, aves e do Homo sapiens marcam a transição entre diferentes períodos geológicos.","A fragmentação de um supercontinente original deu origem à configuração atual dos continentes.","Processos vulcânicos e movimentos da crosta terrestre estão associados à formação de cadeias de montanhas em diferentes eras."]'::jsonb,'[["Crosta terrestre","Camada mais externa e fina da estrutura interna da Terra."],["Manto","Camada interna situada entre a crosta e o núcleo, dividida em superior e inferior."],["Núcleo","Camada mais interna da Terra, dividida em núcleo externo e núcleo interno."],["Era geológica","Grande intervalo de tempo usado para organizar a história da Terra."],["Pangeia","Massa continental única que reunia os continentes atuais antes de sua fragmentação."]]'::jsonb,'["crosta terrestre","manto superior","manto inferior","núcleo externo","núcleo interno","era geológica","Pangeia","vulcanismo","dobramento","Cenozoico"]'::jsonb,'["a Terra é dividida em camadas concêntricas, da crosta ao núcleo interno","as eras geológicas vão do Pré-Cambriano ao Cenozoico","o Homo sapiens surge na era Cenozoica","os continentes atuais resultam da fragmentação de uma massa continental única","atividade vulcânica e movimentos da crosta formam cadeias de montanhas"]'::jsonb,0)
