insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('geo-relevo-solos','geografia','Módulo 8','Relevo e solos do Brasil','O relevo brasileiro varia por região: o Norte tem predomínio de depressões e planaltos de baixa altitude; o Nordeste combina planaltos cristalinos e sedimentares com planícies e tabuleiros litorâneos; Sudeste e Centro-Oeste apresentam planaltos, chapadas e a planície do Pantanal; o Sul tem planaltos com depressões periféricas e a planície da lagoa dos Patos. Já o solo se forma a partir de meteorização, erosão, transporte e sedimentação, sendo constituído por partes minerais, água, ar e matéria orgânica, organizadas em horizontes (O, A, B e C) que vão da camada mais orgânica e escura até a rocha matriz.','["O relevo de cada região brasileira combina, em proporções diferentes, planaltos, planícies e depressões.","O Pantanal é descrito como a planície mais típica e homogênea do território brasileiro.","A formação do solo depende de meteorização, erosão, transporte e sedimentação de materiais rochosos.","O solo é constituído por partes sólidas minerais, matéria orgânica, água e ar, distribuídos entre poros e partículas.","Os horizontes do solo (O, A, B e C) representam camadas com composição e função diferentes, da superfície até a rocha matriz."]'::jsonb,'[["Planalto","Forma de relevo elevada e relativamente plana, geralmente delimitada por bordas mais altas."],["Depressão","Área de relevo rebaixada em relação ao entorno."],["Meteorização","Processo de desagregação e alteração das rochas em contato com o ambiente."],["Horizonte do solo","Camada do solo com características próprias de composição e cor."],["Sedimentação","Depósito de partículas transportadas por água, vento ou gelo."]]'::jsonb,'["planalto","planície","depressão","Pantanal","meteorização","erosão","sedimentação","horizonte do solo","matéria orgânica","relevo regional"]'::jsonb,'["o relevo brasileiro varia de região para região, combinando planaltos, planícies e depressões","o Pantanal é a planície mais típica e homogênea do Brasil","o solo resulta de meteorização, erosão, transporte e sedimentação de rochas","o horizonte O é o mais superficial e rico em matéria orgânica em decomposição","os horizontes do solo se organizam em camadas até alcançar a rocha matriz"]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('geo-recursos-minerais','geografia','Módulo 9','Recursos minerais do Brasil','Os recursos minerais não energéticos se dividem em minerais metálicos (como ferro, alumínio, cobre e zinco) e minerais não metálicos (como fosfato, potássio e sal marinho). O Quadrilátero Ferrífero, em Minas Gerais, é uma das principais áreas de concentração de jazidas minerais do país, com destaque para o minério de ferro. A produção desse polo é escoada principalmente pela Estrada de Ferro Vitória a Minas até o Complexo Portuário de Tubarão, no Espírito Santo, o que conecta a extração mineral do interior à exportação pelo litoral.','["Minerais metálicos incluem ferro, alumínio, cobre, zinco, manganês e estanho, entre outros.","Minerais não metálicos incluem fosfato, potássio e sal marinho, usados sobretudo na indústria e na agricultura.","O Quadrilátero Ferrífero, em Minas Gerais, concentra importantes jazidas de minério de ferro e outros minerais metálicos.","A Estrada de Ferro Vitória a Minas conecta a área de extração mineral ao Complexo Portuário de Tubarão, no Espírito Santo.","A infraestrutura ferroviária e portuária é decisiva para viabilizar a exportação dos minérios extraídos no interior do país."]'::jsonb,'[["Mineral metálico","Recurso mineral do qual se extraem metais, como ferro e alumínio."],["Mineral não metálico","Recurso mineral sem caráter metálico, como fosfato e potássio."],["Quadrilátero Ferrífero","Região de Minas Gerais com grande concentração de jazidas de minério de ferro."],["Jazida","Concentração natural de um recurso mineral em quantidade economicamente aproveitável."],["Escoamento da produção","Transporte do recurso extraído até os portos ou centros de consumo."]]'::jsonb,'["mineral metálico","mineral não metálico","Quadrilátero Ferrífero","minério de ferro","jazida","Estrada de Ferro Vitória a Minas","Complexo Portuário de Tubarão","exportação mineral"]'::jsonb,'["ferro, alumínio, cobre e zinco são exemplos de minerais metálicos","fosfato, potássio e sal marinho são exemplos de minerais não metálicos","o Quadrilátero Ferrífero está localizado em Minas Gerais","a Estrada de Ferro Vitória a Minas liga a área de mineração ao litoral do Espírito Santo","o Complexo Portuário de Tubarão é um dos destinos do minério extraído em Minas Gerais"]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('historia-5','historia','Módulo 5','Barroco no Brasil colonial','O Barroco se divide em duas grandes tendências: o cultismo, marcado por jogos de palavras, linguagem rebuscada e temática amorosa, e o conceptismo, marcado por jogos de ideias, raciocínios elaborados e temática religiosa. No Brasil colonial, essa estética aparece nos sermões do padre Antônio Vieira, que atua como intérprete de sinais divinos ligado à ideologia da Contrarreforma e discute religião, política e sociedade, e na poesia de Gregório de Matos, conhecido como ''Boca do Inferno'', que combina poesia lírica e erótica (amor carnal e malícia), poesia religiosa (busca de perdão), poesia satírica (crítica social) e poesia reflexiva (consciência da efemeridade das coisas).','["Cultismo valoriza o jogo de palavras, a linguagem rebuscada e a temática amorosa.","Conceptismo valoriza o jogo de ideias, o raciocínio elaborado e a temática religiosa.","Antônio Vieira usa o sermão para interpretar sinais divinos e discutir religião, política e sociedade, alinhado à Contrarreforma.","Gregório de Matos, apelidado ''Boca do Inferno'', escreve poesia lírica, erótica, religiosa, satírica e reflexiva.","A poesia satírica de Gregório de Matos funciona como instrumento de crítica social na sociedade colonial baiana."]'::jsonb,'[["Cultismo","Tendência barroca centrada no jogo de palavras e na linguagem rebuscada."],["Conceptismo","Tendência barroca centrada no jogo de ideias e no raciocínio elaborado."],["Contrarreforma","Reação católica à Reforma Protestante, marcada por forte apelo religioso e persuasivo na arte."],["Sermão","Gênero textual religioso usado por Antônio Vieira para interpretar e ensinar."],["Poesia satírica","Poesia que critica costumes e comportamentos da sociedade."]]'::jsonb,'["cultismo","conceptismo","Barroco","Antônio Vieira","sermão","Contrarreforma","Gregório de Matos","poesia satírica","poesia religiosa","Boca do Inferno"]'::jsonb,'["cultismo prioriza jogo de palavras e conceptismo prioriza jogo de ideias","Antônio Vieira é autor de sermões ligados à Contrarreforma","Gregório de Matos ficou conhecido como ''Boca do Inferno''","a poesia de Gregório de Matos inclui vertentes lírica, erótica, religiosa, satírica e reflexiva","o Barroco no Brasil colonial combina temas religiosos e temas profanos"]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('historia-6','historia','Módulo 6','Expansão europeia e conquista da América','A expansão marítima europeia dos séculos XV e XVI conectou partes do mundo que antes não se relacionavam diretamente, colocando em contato sociedades africanas, americanas e europeias. No território que hoje é o Brasil, viviam diferentes culturas indígenas (como tupi-guarani, jê, aruak e karib) antes de 1500. Na América espanhola, os impérios Inca e Asteca tinham estruturas políticas complexas, sendo o Inca mais centralizado e o Asteca organizado como uma federação que subordinava outros grupos, como os tlaxcalas e totonacas. A conquista espanhola, liderada por Hernán Cortés contra os astecas e por Francisco Pizarro contra os incas, combinou armas de fogo, cavalos, alianças com povos indígenas rivais e doenças trazidas pelos europeus, resultando em grande mortalidade indígena, exploração do trabalho e imposição de valores e da língua europeia.','["A expansão marítima dos séculos XV e XVI aproximou regiões do mundo que antes tinham pouco ou nenhum contato direto.","Antes de 1500, o território brasileiro já era ocupado por diferentes culturas indígenas, como tupi-guarani, jê, aruak e karib.","O Império Inca tinha estrutura política centralizada, enquanto o Império Asteca era organizado de forma federativa, subordinando outros povos.","Hernán Cortés conquistou o Império Asteca e Francisco Pizarro conquistou o Império Inca, usando armas, cavalos e alianças com grupos indígenas rivais.","As doenças trazidas pelos europeus, como varíola e sarampo, tiveram papel central na altíssima mortalidade das populações indígenas."]'::jsonb,'[["Expansão marítima","Processo de exploração e domínio de novas rotas e territórios pelos europeus a partir do século XV."],["Império Asteca","Império mesoamericano de estrutura federativa, conquistado por Hernán Cortés."],["Império Inca","Império andino de estrutura política centralizada, conquistado por Francisco Pizarro."],["Genocídio indígena","Extermínio em massa de populações indígenas durante a conquista europeia."],["Sincretismo cultural","Mistura de elementos culturais europeus e indígenas ou africanos originada do contato entre os povos."]]'::jsonb,'["expansão marítima","povos indígenas","tupi-guarani","Império Inca","Império Asteca","Hernán Cortés","Francisco Pizarro","conquista espanhola","doenças europeias","contato luso-africano"]'::jsonb,'["a expansão europeia dos séculos XV e XVI ligou partes do mundo antes desconectadas","tupi-guarani, jê, aruak e karib são exemplos de troncos linguísticos indígenas no Brasil pré-1500","Hernán Cortés submeteu o Império Asteca e seu imperador Montezuma","Francisco Pizarro submeteu o Império Inca e seu imperador Atahualpa","doenças como varíola e sarampo contribuíram fortemente para a mortalidade indígena durante a conquista"]'::jsonb,10)
