-- ===== Matérias NOVAS (modulos.md): Literatura, Produção de texto, Bio B, Física B, Química B =====
begin;
insert into public.subjects (id,title,description,theme,order_index) values ('literatura','Literatura e Arte','Renascimento e Camões, Quinhentismo e Barroco.','violet',130)
on conflict (id) do update set title=excluded.title, description=excluded.description, theme=excluded.theme, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('literatura-3','literatura','Módulo 3','Renascimento e Camões','O Renascimento (séc. XV–XVI) retoma a Antiguidade Clássica e coloca o ser humano no centro (antropocentrismo), valorizando razão, equilíbrio e harmonia. Na língua portuguesa, Luís de Camões é o nome máximo: na épica escreve Os Lusíadas (1572), epopeia em 10 cantos e versos decassílabos que narra a viagem de Vasco da Gama às Índias e exalta o povo português; na lírica cultiva a ''medida velha'' (redondilhas, temas populares) e a ''medida nova'' (sonetos decassílabos de influência clássica e platônica), tratando do amor idealizado e do ''desconcerto do mundo''.','["Renascimento: antropocentrismo, racionalismo, equilíbrio e resgate da Antiguidade Clássica.","Os Lusíadas: epopeia de 10 cantos, 1102 estrofes em oitava-rima (ABABABCC) e versos decassílabos.","Estrutura da epopeia: proposição, invocação, dedicatória, narração e epílogo.","Episódios célebres: Inês de Castro, Velho do Restelo, Gigante Adamastor e Ilha dos Amores.","Lírica: ''medida velha'' (redondilhas) e ''medida nova'' (sonetos decassílabos)."]'::jsonb,'[["Epopeia","Longo poema narrativo, em tom elevado, sobre feitos heroicos de um povo."],["Antropocentrismo","Visão que coloca o ser humano no centro, típica do Renascimento."],["Medida nova","Verso decassílabo e formas como o soneto, de inspiração clássica italiana."],["Redondilha","Verso de 5 (menor) ou 7 (maior) sílabas, da ''medida velha''."],["Desconcerto do mundo","Tema camoniano da desordem e instabilidade da vida."]]'::jsonb,'["renascimento","camões","os lusíadas","epopeia","decassílabo","soneto","lírica","medida velha","medida nova","antropocentrismo","vasco da gama","adamastor"]'::jsonb,'["Os Lusíadas foram publicados em 1572 e têm como assunto central a viagem de Vasco da Gama (1497–1499).","A obra mistura mitologia greco-romana e referências bíblicas (fusionismo).","O episódio do Velho do Restelo traz uma voz crítica às Grandes Navegações.","O soneto ''Amor é fogo que arde sem se ver'' é exemplo da lírica de ''medida nova''.","A poesia em ''medida velha'' resgata temas da cultura popular e ibérica medieval."]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('literatura-4','literatura','Módulo 4','Quinhentismo no Brasil','O Quinhentismo reúne as primeiras manifestações escritas em terras brasileiras no século XVI, ligadas à colonização. Divide-se em literatura de informação (relatos de viajantes e cronistas sobre a nova terra, como a Carta de Pero Vaz de Caminha, de 1500) e literatura de catequese (textos jesuíticos voltados à conversão dos indígenas, com destaque para o padre José de Anchieta e seus autos, poemas e a gramática do tupi). Não é ainda uma literatura ''brasileira'', mas um conjunto de textos produzidos sobre o Brasil.','["Quinhentismo = primeiras manifestações literárias no Brasil colonial (séc. XVI).","Literatura de informação: relatos de cronistas e viajantes sobre a nova terra.","Carta de Pero Vaz de Caminha (1500): ''certidão de nascimento'' do Brasil.","Literatura de catequese: textos jesuíticos de conversão dos indígenas.","José de Anchieta: autos, poemas e a gramática da língua tupi."]'::jsonb,'[["Quinhentismo","Conjunto de textos produzidos no Brasil no século XVI (anos 1500)."],["Literatura de informação","Relatos descritivos da terra recém-''descoberta''."],["Literatura de catequese","Produção jesuítica voltada à conversão religiosa."],["Auto","Peça teatral curta de caráter religioso e didático."],["Cronista","Autor que registra fatos e observações de viagem."]]'::jsonb,'["quinhentismo","carta de caminha","literatura de informação","catequese","anchieta","jesuítas","colonização","tupi","crônica","auto"]'::jsonb,'["A Carta de Caminha foi escrita em 1500 e descreve a terra e os indígenas ao rei de Portugal.","A produção do período é em português (e tupi), feita por europeus.","Os jesuítas usavam o teatro (autos) como instrumento de catequese.","José de Anchieta escreveu uma das primeiras gramáticas do tupi.","O Quinhentismo não constitui uma literatura nacional, mas textos sobre o Brasil."]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('literatura-5','literatura','Módulo 5','Barroco: Vieira e Gregório','O Barroco (séc. XVII) nasce da crise entre os valores medievais (teocentrismo) e renascentistas (antropocentrismo), expressando conflito, dualidade e forte religiosidade. Caracteriza-se pelo cultismo (jogo de imagens e metáforas, ''culto à forma'') e pelo conceptismo (jogo de ideias e raciocínio). No Brasil destacam-se o padre Antônio Vieira, mestre da prosa nos Sermões (conceptismo e persuasão), e Gregório de Matos, o ''Boca do Inferno'', autor de poesia religiosa, amorosa e, sobretudo, satírica contra a sociedade baiana.','["Barroco (séc. XVII): conflito entre fé (teocentrismo) e razão (antropocentrismo).","Cultismo: jogo de palavras e imagens (metáforas, antíteses) — culto à forma.","Conceptismo: jogo de ideias e raciocínio lógico-argumentativo.","Padre Antônio Vieira: os Sermões, marco da prosa conceptista.","Gregório de Matos: poesia religiosa, amorosa e satírica (''Boca do Inferno'')."]'::jsonb,'[["Cultismo","Estilo barroco baseado em jogos de imagem e excesso de figuras."],["Conceptismo","Estilo barroco baseado no jogo de ideias e na argumentação."],["Antítese","Figura que aproxima ideias opostas, típica do Barroco."],["Sermão","Texto religioso persuasivo; gênero dominado por Vieira."],["Sátira","Poesia crítica e mordaz, marca de Gregório de Matos."]]'::jsonb,'["barroco","cultismo","conceptismo","antítese","vieira","sermões","gregório de matos","sátira","teocentrismo","boca do inferno"]'::jsonb,'["O Barroco brasileiro tem como marco 1601 (Prosopopeia, de Bento Teixeira).","Vieira defendeu indígenas e usou a argumentação conceptista em seus sermões.","Gregório de Matos ficou conhecido como ''Boca do Inferno'' pela poesia satírica.","A antítese e o paradoxo expressam o conflito espiritual barroco.","O cultismo é associado ao espanhol Luís de Góngora (''gongorismo'')."]'::jsonb,20)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.subjects (id,title,description,theme,order_index) values ('producao-texto','Produção de Texto','Comunicação digital, redes sociais e dissertação.','blue',140)
on conflict (id) do update set title=excluded.title, description=excluded.description, theme=excluded.theme, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('producao-texto-3','producao-texto','Módulo 3','Tecnologias Digitais (TDIC)','As Tecnologias Digitais da Informação e da Comunicação (TDIC) são o estágio mais recente de uma longa evolução: primado da fala, invenção da escrita, comunicação a distância (telefone, rádio, TV) e, por fim, os meios digitais (computadores, celulares, internet). No ambiente digital surgem gêneros próprios (post, tweet, e-mail, chat) marcados pela efemeridade — aparecem e desaparecem rápido — e por uma variedade informal, o ''internetês''. Compreender esses recursos é essencial para produzir textos adequados a cada suporte e situação.','["Estágios da comunicação: fala, escrita, comunicação a distância e meios digitais.","TDIC: tecnologias digitais que integram informação e comunicação.","Gêneros digitais surgem e desaparecem rapidamente (efemeridade).","''Internetês'': variedade linguística informal típica do meio digital.","A tela é um novo suporte que muda a forma de ler e escrever."]'::jsonb,'[["TDIC","Tecnologias Digitais da Informação e da Comunicação."],["Gênero digital","Tipo de texto próprio do meio digital (post, chat, e-mail...)."],["Internetês","Variedade informal e abreviada usada na internet."],["Suporte","Meio físico/virtual em que o texto circula (papel, tela...)."],["Efemeridade","Curta duração: gêneros digitais mudam com rapidez."]]'::jsonb,'["tdic","comunicação","escrita","meios digitais","gênero digital","internetês","suporte","tela","variedade linguística","efemeridade"]'::jsonb,'["A comunicação humana evoluiu da fala à escrita e, depois, aos meios digitais.","Romanos já trocavam mensagens em rede usando papiros e tábuas de cera.","O ''internetês'' simplifica a escrita (ex.: ''blz'', ''tbm'', ''vc'').","Cada gênero digital pede uma adequação de linguagem ao contexto.","A efemeridade dos gêneros exige (re)aprendizado constante das TDIC."]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('producao-texto-4','producao-texto','Módulo 4','Redes sociais e dissertação','As redes sociais ampliaram a circulação de informação e a interação, mas trouxeram questões como bolhas, fake news e o controle de dados pessoais pelas plataformas. A partir desse repertório, o módulo orienta a produção da dissertação argumentativa no modelo dos exames de seleção: tese clara, argumentos consistentes (dados, exemplos, causas e consequências) e proposta de intervenção, com coesão e norma-padrão.','["Redes sociais ampliam interação, mas geram bolhas e desinformação.","Dados pessoais são coletados e influenciam o comportamento dos usuários.","Dissertação argumentativa: tese + argumentos + proposta de intervenção.","Bons argumentos usam dados, exemplos e relações de causa e consequência.","Coesão, coerência e norma-padrão são exigidas no texto dissertativo."]'::jsonb,'[["Dissertação argumentativa","Texto que defende uma tese com argumentos."],["Tese","Ponto de vista central que o texto defende."],["Proposta de intervenção","Solução apresentada na conclusão da dissertação."],["Fake news","Notícia falsa divulgada como verdadeira."],["Bolha","Ambiente em que se vê só o que confirma a própria opinião."]]'::jsonb,'["redes sociais","dissertação","argumentação","tese","proposta de intervenção","coesão","coerência","fake news","dados","norma-padrão"]'::jsonb,'["A dissertação argumentativa é o gênero mais cobrado em vestibulares e no Enem.","A proposta de intervenção deve respeitar os direitos humanos.","Plataformas digitais lucram com a coleta e o uso de dados pessoais.","Argumentos de autoridade citam fontes confiáveis para sustentar a tese.","A repetição em ''bolhas'' tende a radicalizar opiniões."]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
