insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('biologia-b-1','biologia-b','Módulo 1','Proteínas e aminoácidos','As proteínas são polímeros formados por aminoácidos unidos por ligações peptídicas. Cada aminoácido tem um grupo amina, um grupo carboxila e um radical (R) variável. Dos 20 aminoácidos, alguns são essenciais (não produzidos pelo corpo e obtidos na dieta — 9 na espécie humana) e outros não essenciais. A sequência de aminoácidos define as estruturas primária, secundária, terciária e quaternária, das quais depende a função (estrutural, enzimática, defesa, transporte). O calor ou o pH podem causar desnaturação, com perda da forma e da função.','["Proteínas = polímeros de aminoácidos unidos por ligações peptídicas.","Aminoácido: grupo amina + grupo carboxila + radical R variável.","Aminoácidos essenciais (9 no ser humano) vêm da alimentação.","Estruturas: primária, secundária, terciária e quaternária.","Desnaturação: calor/pH alteram a forma e anulam a função."]'::jsonb,'[["Aminoácido","Unidade que forma as proteínas."],["Ligação peptídica","União entre o grupo carboxila e o grupo amina de dois aminoácidos."],["Aminoácido essencial","Aquele que o organismo não sintetiza e obtém na dieta."],["Desnaturação","Perda da estrutura tridimensional e da função da proteína."],["Radical (R)","Parte variável que diferencia cada aminoácido."]]'::jsonb,'["proteína","aminoácido","ligação peptídica","peptídeo","essencial","desnaturação","estrutura primária","radical","polímero","função"]'::jsonb,'["Existem 20 aminoácidos que combinados formam todas as proteínas.","O ser humano tem 9 aminoácidos essenciais e 11 não essenciais.","A função de uma proteína depende de sua forma tridimensional.","A desnaturação geralmente é irreversível (ex.: clara de ovo cozida).","Proteínas atuam como enzimas, anticorpos, transportadoras e estruturais."]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('biologia-b-2','biologia-b','Módulo 2','Enzimas','Enzimas são proteínas que atuam como catalisadores biológicos: aceleram reações diminuindo a energia de ativação, sem serem consumidas. Atuam com alta especificidade pelo modelo chave-fechadura, ligando-se ao substrato no sítio ativo. Sua atividade depende de temperatura e pH ótimos; fora dessas faixas, a enzima desnatura. Muitas precisam de cofatores ou coenzimas (frequentemente vitaminas) para funcionar.','["Enzimas são catalisadores biológicos de natureza proteica.","Diminuem a energia de ativação e não são consumidas na reação.","Especificidade: modelo chave-fechadura (enzima–substrato).","Atividade depende de temperatura e pH ótimos.","Cofatores e coenzimas (vitaminas) auxiliam a catálise."]'::jsonb,'[["Enzima","Proteína que catalisa (acelera) reações biológicas."],["Substrato","Molécula sobre a qual a enzima atua."],["Sítio ativo","Região da enzima que se liga ao substrato."],["Energia de ativação","Energia mínima para iniciar uma reação."],["Coenzima","Molécula auxiliar (muitas vezes vitamina) da enzima."]]'::jsonb,'["enzima","catalisador","substrato","sítio ativo","chave-fechadura","energia de ativação","temperatura ótima","ph ótimo","coenzima","especificidade"]'::jsonb,'["Enzimas terminam frequentemente no sufixo ''-ase'' (ex.: amilase, lipase).","Cada enzima atua sobre um substrato específico.","Acima da temperatura ótima, a enzima desnatura e perde função.","A enzima não é consumida e pode catalisar muitas reações.","Muitas vitaminas funcionam como coenzimas no metabolismo."]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('biologia-b-3','biologia-b','Módulo 3','Ácidos nucleicos','Os ácidos nucleicos — DNA e RNA — guardam e transmitem a informação genética. São polímeros de nucleotídeos, cada um formado por um fosfato, uma pentose (desoxirribose no DNA, ribose no RNA) e uma base nitrogenada. O DNA é uma dupla-hélice com bases A-T e C-G (pareamento complementar) e armazena o código; o RNA é simples-fita, usa uracila no lugar da timina e participa da síntese de proteínas (mensageiro, transportador e ribossômico).','["Ácidos nucleicos: DNA e RNA, polímeros de nucleotídeos.","Nucleotídeo = fosfato + pentose + base nitrogenada.","DNA: dupla-hélice; pareamento A-T e C-G.","RNA: fita simples, com uracila no lugar da timina.","RNA participa da síntese de proteínas (mensageiro, transportador, ribossômico)."]'::jsonb,'[["Nucleotídeo","Unidade do ácido nucleico: fosfato + pentose + base."],["DNA","Ácido desoxirribonucleico; guarda a informação genética."],["RNA","Ácido ribonucleico; atua na síntese de proteínas."],["Base nitrogenada","A, T, C, G (e U no RNA), que codificam a informação."],["Pareamento","Ligação complementar entre bases (A-T/A-U e C-G)."]]'::jsonb,'["dna","rna","nucleotídeo","base nitrogenada","dupla-hélice","adenina","timina","uracila","pentose","código genético"]'::jsonb,'["No DNA, a adenina pareia com timina e a citosina com guanina.","No RNA, a timina é substituída pela uracila.","A pentose do DNA é a desoxirribose; a do RNA é a ribose.","A estrutura em dupla-hélice foi proposta por Watson e Crick (1953).","A sequência de bases do DNA forma o código genético."]'::jsonb,20)
