insert into public.subjects (id,title,description,theme,order_index) values ('fisica-b','Física B','Estática: equilíbrio, momento e corpos extensos.','blue',160)
on conflict (id) do update set title=excluded.title, description=excluded.description, theme=excluded.theme, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('fisica-b-1','fisica-b','Módulo 1','Equilíbrio do ponto material','Um ponto material está em equilíbrio quando a resultante das forças que agem sobre ele é nula (R = 0). No equilíbrio estático ele permanece em repouso. Para resolver problemas, decompõem-se as forças nos eixos x e y e impõe-se que a soma em cada eixo seja zero. Forças concorrentes podem ser somadas pela regra do paralelogramo; casos com três forças costumam usar decomposição trigonométrica.','["Equilíbrio do ponto material: resultante das forças igual a zero (R = 0).","Equilíbrio estático = repouso; dinâmico = velocidade constante.","Decompõem-se as forças em x e y: ΣFx = 0 e ΣFy = 0.","Forças concorrentes somam-se pela regra do paralelogramo.","Peso, normal e tração são forças comuns nesses problemas."]'::jsonb,'[["Ponto material","Corpo cujas dimensões são desprezíveis no problema."],["Força resultante","Soma vetorial de todas as forças que agem no corpo."],["Equilíbrio estático","Estado de repouso com resultante nula."],["Decomposição","Separar uma força em componentes nos eixos x e y."],["Força normal","Força de contato perpendicular à superfície."]]'::jsonb,'["equilíbrio","ponto material","força resultante","vetor","decomposição","repouso","normal","tração","peso","estática"]'::jsonb,'["No equilíbrio de um ponto material a resultante das forças é nula.","Equilíbrio estático significa repouso; dinâmico, velocidade constante.","As condições ΣFx = 0 e ΣFy = 0 resolvem o equilíbrio no plano.","Forças concorrentes têm linhas de ação que se cruzam num ponto.","A regra do paralelogramo soma duas forças concorrentes."]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('fisica-b-2','fisica-b','Módulo 2','Momento (torque) de uma força','O momento (ou torque) mede a capacidade de uma força provocar rotação em torno de um eixo. É dado por M = F · b, onde b é o braço de alavanca (distância perpendicular entre a linha de ação da força e o eixo). Quando a força é oblíqua, usa-se M = F · L · sen α. O momento é horário ou anti-horário conforme o sentido de giro, sendo positivo/negativo por convenção.','["Momento (torque): tendência de uma força girar um corpo em torno de um eixo.","M = F · b, sendo b o braço de alavanca (distância perpendicular).","Força oblíqua: M = F · L · sen α.","O momento é horário ou anti-horário (convenção de sinais).","Unidade no SI: newton-metro (N·m)."]'::jsonb,'[["Momento (torque)","Grandeza que mede o efeito de rotação de uma força."],["Braço de alavanca","Distância perpendicular do eixo à linha de ação da força."],["Linha de ação","Reta que contém o vetor força."],["Eixo de rotação","Linha em torno da qual o corpo pode girar."],["Newton-metro","Unidade de momento (N·m) no SI."]]'::jsonb,'["momento","torque","braço de alavanca","rotação","eixo","força oblíqua","horário","anti-horário","newton-metro","linha de ação"]'::jsonb,'["Quanto maior o braço de alavanca, maior o momento para a mesma força.","O momento é máximo quando a força é perpendicular à barra (sen 90° = 1).","A unidade de momento no SI é o newton-metro (N·m).","Uma força cuja linha de ação passa pelo eixo tem momento nulo.","Chaves longas facilitam soltar parafusos por aumentarem o braço."]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('fisica-b-3','fisica-b','Módulo 3','Equilíbrio dos corpos extensos','Um corpo extenso está em equilíbrio quando não há translação nem rotação. Para isso, exigem-se duas condições: a resultante das forças é nula (ΣF = 0, sem translação) e a soma dos momentos em relação a qualquer eixo é nula (ΣM = 0, sem rotação). Essas condições explicam o funcionamento de gangorras, alavancas, pontes e do centro de gravidade dos corpos.','["Corpo extenso: tem dimensões que importam (pode transladar e girar).","1ª condição: ΣF = 0 (não há translação).","2ª condição: ΣM = 0 (não há rotação).","Aplicações: gangorra, alavancas, pontes e centro de gravidade.","Momentos horários e anti-horários se equilibram (ΣM = 0)."]'::jsonb,'[["Corpo extenso","Corpo cujas dimensões não podem ser desprezadas."],["Translação","Movimento em que todos os pontos se deslocam igualmente."],["Rotação","Giro do corpo em torno de um eixo."],["Centro de gravidade","Ponto onde se considera aplicado o peso do corpo."],["Alavanca","Máquina simples que amplia força usando um apoio."]]'::jsonb,'["corpo extenso","equilíbrio","translação","rotação","momento","centro de gravidade","alavanca","gangorra","apoio","estática"]'::jsonb,'["O equilíbrio de um corpo extenso exige ΣF = 0 e ΣM = 0.","Numa gangorra equilibrada, os momentos dos dois lados se igualam.","Alavancas multiplicam força ao custo de deslocamento.","O centro de gravidade influencia a estabilidade do corpo.","Um corpo pode ter resultante nula e ainda girar se ΣM ≠ 0."]'::jsonb,20)
