insert into public.subjects (id,title,description,theme,order_index) values ('quimica-b','Química B','Substâncias, misturas e métodos de separação.','yellow',170)
on conflict (id) do update set title=excluded.title, description=excluded.description, theme=excluded.theme, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('quimica-b-1','quimica-b','Módulo 1','Substâncias e misturas','A matéria pode ser substância pura (composição fixa: substância simples, formada por um elemento, ou composta, por mais de um) ou mistura (dois ou mais componentes). Misturas homogêneas têm uma só fase (soluções, como sal em água); heterogêneas têm duas ou mais fases (água e areia). Misturas especiais, como ligas e o ar, e os pontos de fusão/ebulição ajudam a distinguir substâncias de misturas.','["Substância pura: composição fixa (simples ou composta).","Mistura: dois ou mais componentes em proporções variáveis.","Homogênea: uma única fase (solução).","Heterogênea: duas ou mais fases.","Pontos de fusão/ebulição constantes indicam substância pura."]'::jsonb,'[["Substância pura","Material de composição e propriedades fixas."],["Mistura","União de duas ou mais substâncias."],["Fase","Porção homogênea e uniforme de um sistema."],["Mistura homogênea","Apresenta uma única fase (solução)."],["Mistura heterogênea","Apresenta duas ou mais fases."]]'::jsonb,'["substância pura","mistura","homogênea","heterogênea","fase","solução","substância simples","substância composta","componente","liga"]'::jsonb,'["Substâncias puras têm pontos de fusão e ebulição constantes.","Uma solução é uma mistura homogênea (uma só fase).","Água e óleo formam uma mistura heterogênea (duas fases).","O ar atmosférico é uma mistura homogênea de gases.","Ligas metálicas, como o bronze, são misturas de metais."]'::jsonb,0)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('quimica-b-2','quimica-b','Módulo 2','Separação de misturas','Separar misturas significa isolar seus componentes usando diferenças de propriedades. Para misturas heterogêneas: filtração (sólido + líquido), decantação (líquidos imiscíveis ou sólido que deposita), centrifugação e peneiração. Para misturas homogêneas: destilação simples (sólido dissolvido em líquido) e evaporação. A escolha do método depende do estado físico e das propriedades (densidade, solubilidade, temperatura de ebulição).','["Separar misturas explora diferenças de propriedades dos componentes.","Heterogêneas: filtração, decantação, centrifugação, peneiração.","Homogêneas: destilação simples e evaporação.","Decantação separa por diferença de densidade.","A escolha do método depende do estado físico e das propriedades."]'::jsonb,'[["Filtração","Separa sólido de líquido (ou gás) com um filtro."],["Decantação","Separa por diferença de densidade, deixando depositar."],["Destilação simples","Separa sólido dissolvido evaporando e condensando o líquido."],["Centrifugação","Acelera a decantação por rotação rápida."],["Solubilidade","Capacidade de uma substância dissolver-se em outra."]]'::jsonb,'["separação","filtração","decantação","destilação","evaporação","centrifugação","peneiração","densidade","solubilidade","mistura"]'::jsonb,'["A filtração retém o sólido e deixa passar o líquido (filtrado).","A decantação aproveita a diferença de densidade entre os componentes.","A destilação simples separa o sal dissolvido da água.","O tratamento de água usa decantação e filtração.","A centrifugação é uma decantação acelerada por rotação."]'::jsonb,10)
on conflict (id) do update set subject_id=excluded.subject_id, title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, key_points=excluded.key_points, glossary=excluded.glossary, concepts=excluded.concepts, facts=excluded.facts, order_index=excluded.order_index, deleted_at=null;
insert into public.modules (id,subject_id,title,subtitle,summary,key_points,glossary,concepts,facts,order_index) values ('quimica-b-3','quimica-b','Módulo 3','Destilação fracionada e petróleo','A destilação fracionada separa líquidos miscíveis com diferentes temperaturas de ebulição, usando uma coluna de fracionamento que permite vaporizar e condensar os componentes em etapas. É a base do refino do petróleo: na torre de fracionamento, as frações mais voláteis (gases, gasolina) saem no topo e as menos voláteis (óleo diesel, lubrificantes, asfalto) na base. Também separa, por exemplo, benzeno e tolueno.','["Destilação fracionada separa líquidos miscíveis com ebulições diferentes.","A coluna de fracionamento separa por etapas de vaporização/condensação.","Refino do petróleo: frações leves no topo, pesadas na base.","Frações: gases, gasolina, querosene, diesel, lubrificantes, asfalto.","Permite separar misturas como benzeno e tolueno."]'::jsonb,'[["Destilação fracionada","Separa líquidos miscíveis por diferença de ebulição."],["Coluna de fracionamento","Dispositivo que separa os vapores em etapas."],["Fração","Conjunto de componentes separados na destilação do petróleo."],["Volatilidade","Facilidade de uma substância evaporar."],["Condensação","Passagem do vapor ao estado líquido."]]'::jsonb,'["destilação fracionada","coluna de fracionamento","petróleo","refino","fração","volatilidade","ebulição","condensação","gasolina","miscível"]'::jsonb,'["A destilação fracionada separa benzeno (T.E. 80 °C) e tolueno (T.E. 110 °C).","No refino, as frações leves saem no topo da torre.","Gasolina, querosene, diesel e asfalto são frações do petróleo.","Quanto mais volátil a fração, mais alto ela sai na coluna.","A coluna de fracionamento melhora a separação de líquidos miscíveis."]'::jsonb,20)
